def p(t,style='body'):return Paragraph(t,S[style])
def h(t):return p(t,'h2')
def note(t):return p('<b>Note.</b> '+t)
def code(t):return p(escape(t).replace('\n','<br/>'),'code')
def steps(items):return [p(f'<b>{i}.</b> {t}') for i,t in enumerate(items,1)]
def bullet(items):return [p('• '+t) for t in items]
def shot(name,caption,width=W):
 im=ImageReader(str(SHOTS/name));iw,ih=im.getSize();img=Image(str(SHOTS/name),width=width,height=width*ih/iw);img.hAlign='CENTER'
 return [img,Spacer(1,5),p(caption,'caption')]
def table(headers,rows,widths):
 data=[[p(escape(x),'cellhead') for x in headers]]+[[p(escape(str(x)),'cell') for x in row] for row in rows]
 tb=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
 tb.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F2F5F7')]),('GRID',(0,0),(-1,-1),.5,colors.HexColor('#D9D9D9')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
 return [tb,Spacer(1,10)]

def page(title,*items):return [p(title,'h1'),*items]
def footer(label):
 def draw(c,d):
  c.saveState();c.setStrokeColor(colors.HexColor('#D9D9D9'));c.line(54,42,558,42)
  c.setFont('Body',8);c.setFillColor(GRAY);c.drawString(54,28,'JatayuOS 1.0 Udaan  |  '+label);c.drawRightString(558,28,str(d.page))
  if d.page>1:c.setFont('Body',8);c.setFillColor(colors.black);c.drawString(54,763,'JATAYUOS DOCUMENTATION');c.drawRightString(558,763,'Made in India')
  c.restoreState()
 return draw

def save(filename,label,pages):
 story=[]
 for i,content in enumerate(pages):
  if i:story.append(PageBreak())
  story.extend(content)
 doc=SimpleDocTemplate(str(OUT/filename),pagesize=(612,792),leftMargin=54,rightMargin=54,topMargin=54,bottomMargin=60,title='JatayuOS '+label,author='JatayuOS documentation',subject='JatayuOS 1.0 Udaan user documentation')
 doc.build(story,onFirstPage=footer(label),onLaterPages=footer(label))
 print(filename,len(pages),'planned pages')

