guide=[]
guide.append([p('JatayuOS Installation Guide','title'),p('JatayuOS 1.0 Udaan','h2'),p('Read this guide before changing disks. It covers starting the live ISO, a clean installation, Windows UEFI manual dual boot and first installed boot. Installer screens depend on the detected disks and firmware mode.'),*shot('boot-menu.png','Normal live-system entry in the supplied BIOS-style VM boot menu.',width=340),h('Prepare first'),*bullet(['Back up personal files to another device and check that the backup opens.','For Windows, save the BitLocker recovery key before boot or partition changes.','Identify the target disk by model, capacity and existing partitions.','Keep the downloaded ISO and its supplied SHA256SUMS file.','Connect power and allow the installation to finish without interruption.']),p('Use disposable virtual disks for a first installation rehearsal. VM success does not prove that another machine or Windows disk layout is safe.'),p('Edition 2 • 5 October 2026 • Based on tested Build 35','small')])
guide.append(page('Verify and start the live system',h('Verify the download'),p('Keep the ISO and SHA256SUMS in the same directory. Open a terminal in that directory and run:'),code('sha256sum -c SHA256SUMS'),p('The ISO entry should report OK. A mismatch means the file differs from the checksum; do not proceed with that copy. A checksum confirms file integrity against the supplied value, not the authenticity of an untrusted download source.'),h('Start from USB or a VM'),p('Write the ISO to a USB using your chosen image writer and carefully select the removable target; writing the image erases that USB. In a VM, attach the ISO as optical media and use a separate empty virtual disk. Match the firmware mode needed for your installation.'),*shot('Welcome-screen.png','Open Installation Guide before selecting Install JatayuOS.',width=430),p('Boot the normal Live system entry. Choose <b>Try JatayuOS</b> and check keyboard, display, networking and files. Then launch <b>Install JatayuOS</b> from the desktop or live welcome. Installation changes require administrator approval.')))
guide.append(page('Clean installation or erase and reinstall',p('<b>Erase disk deletes data on the selected target disk.</b> This route is appropriate only when that disk’s existing contents can be removed. It does not preserve Windows or personal files on that disk.'),*steps(['Launch Install JatayuOS from the live session.','Review the installer’s location/timezone and keyboard settings. The live welcome’s lack of a language selector does not remove the installer’s normal settings pages.','On partitioning, choose the intended disk and the erase option only after checking its model and capacity.','Enter your user details and a strong, unique password. Store it securely.','Read the final summary. Confirm every partition that will be created, formatted or removed belongs to the intended target.','Start installation. Wait for completion and avoid disconnecting power or the target drive.','Restart when prompted and remove or detach the installation media when safe. Boot the installed disk.']),h('Manual installation on an empty disk'),p('Use manual partitioning only if you understand the selected layout. An ext4 root filesystem mounted at <b>/</b> is required. UEFI installation also needs an appropriate EFI System Partition mounted at <b>/boot/efi</b>. BIOS and UEFI requirements differ; do not apply an arbitrary UEFI partition recipe to a BIOS layout.'),h('Before approving the summary'),*bullet(['The selected disk and partition sizes match your plan.','Required mount points are assigned.','No unrelated disk or preserved data partition is marked for formatting.','The installer is booted in the intended firmware mode.']),note('Alongside installation appears only when the installer supports the detected layout. If it is absent, do not assume the disk is suitable or force an unreviewed workaround.')))
guide.append(page('Windows UEFI manual dual boot',p('Use this route only after preparing a backup and the BitLocker recovery key. Existing Microsoft EFI files, Windows partitions and recovery partitions must be preserved.'),h('Prepare from Windows'),*steps(['Use Windows Disk Management to shrink a supported Windows volume and leave unallocated space for JatayuOS.','Disable Windows Fast Startup and shut Windows down fully. Do not edit a hibernated Windows filesystem from Linux.','Boot the JatayuOS USB in the same firmware mode as Windows, normally UEFI.']),h('Assign partitions in Calamares'),*table(['Partition','Action'],[['New Linux root in unallocated space','Create ext4 assign / and format only this new filesystem'],['Existing EFI System Partition','Assign /boot/efi and leave formatting disabled'],['Windows NTFS partitions','Leave unchanged'],['Microsoft reserved and recovery partitions','Leave unchanged']],[209,295]),p('Double-check the EFI partition on machines with multiple disks or multiple EFI partitions. Do not identify it by size alone. If the layout is uncertain, stop before applying changes.'),h('Review and test'),p('Read the final summary and confirm that no Windows, Microsoft reserved, recovery or existing EFI filesystem will be formatted. After installation, test both JatayuOS and Windows Boot Manager. Keep the BitLocker recovery key available for Windows.'),note('GRUB detection cannot recreate missing Microsoft EFI files. If Windows already cannot boot because those files are absent, use a separate Windows recovery process before assuming Linux installation will repair it.'),p('Detailed project policy: docs/DUAL-BOOT.md in the JatayuOS repository.')))
guide.append(page('First installed boot',*shot('desktop.png','The supplied live desktop shows the visual identity; an installed desktop need not retain the live installer icons.',width=430),*steps(['Boot the installed disk with the ISO detached or USB removed. Sign in with the user account created during installation.','Open Aarambh and use its help or shortcuts. Uncheck Show Aarambh when I sign in if you want it disabled at future logins.','Connect to the network and confirm the system date and time.','Refresh updates and inspect the available package list.','Check sound, input, Dolphin, Firefox and the Jatayu Tools applications.']),code('timedatectl status\nsudo apt update\napt list --upgradable'),p('The time daemon is included in this version. Synchronization still needs reachable network time. An error-free APT refresh followed by “All packages are up to date” is a valid result; daily upgrades are not guaranteed.'),p('Test wallpaper persistence and a clean restart. For dual boot, also start Windows and confirm access to its files.')))
guide.append(page('Installation troubleshooting and checklist',*table(['Problem','Action'],[['Installer will not launch','Use the live ISO and check authentication or visible error text'],['Target disk is missing','Check firmware storage mode VM disk attachment and controller support'],['Black screen or startup stall','Record firmware mode graphics settings and last visible screen'],['No alongside option','Review the detected layout do not assume manual changes are safe'],['Windows missing from GRUB','Check Windows Boot Manager in firmware and whether its EFI files exist'],['Update signature not valid yet','Verify clock network and active time synchronization']],[194,310]),h('Record the installation result'),*bullet(['ISO checksum and SOURCE-COMMIT.txt recorded.','Live session reaches the desktop and essential hardware works.','Installation completes on the intended disk.','Installed login works with installation media removed.','Time synchronization and package refresh work.','Jatayu applications launch and wallpaper persists.','Windows boot tested separately if dual boot was configured.']),h('References and limits'),p('This guide follows the repository’s Calamares policy in docs/DUAL-BOOT.md and startup behavior in apps/app.py. It uses owner-supplied VM images and the owner’s acceptance report for Build 35.'),p('Secure Boot, encryption, BIOS, Windows layouts and Android require separate tests. No partition-screen captures were supplied.','small'),p('Project: <link href="https://github.com/jatayuos4u/jatayuos" color="#172A3D">github.com/jatayuos4u/jatayuos</link><br/>Website: <link href="https://jatayuos.in" color="#172A3D">jatayuos.in</link><br/>APT reference: <link href="https://www.debian.org/doc/manuals/debian-reference/ch02.en.html" color="#172A3D">Debian Reference Chapter 2</link>.'),p('Stop before confirmation if the disk layout is unfamiliar.','small')))
save('INSTALLATION-GUIDE.pdf','Installation Guide',guide)

faq=[]
def qa(q,a):return [h(q),p(a)]
faq.append([p('JatayuOS Frequently Asked Questions','title'),p('JatayuOS 1.0 Udaan • Edition 2 • 5 October 2026'),p('Quick answers for JatayuOS 1.0, with Build 35 testing screenshots. Use the User Manual for workflows and the Installation Guide before changing disks.'),*qa('What is JatayuOS','An independent operating-system project by Anup Yadav, made in India and based on Debian 13 with KDE Plasma. It includes everyday applications and a dedicated Jatayu Tools category.'),*qa('Is it a government operating system','No. Made in India identifies the project’s origin. Sarkar Setu links to services run by other organizations; it does not make JatayuOS an official government portal.'),*qa('Can I try it without installing','Yes. Boot the live ISO and choose Try JatayuOS. Changes in an ordinary live session may disappear after restarting; do not rely on it as permanent file storage.'),*qa('Is internet required','The desktop, bundled help, Creative Studio and bundled wallpapers can be used offline. Package downloads, linked websites, online services and the initial Android image download require internet.'),*qa('What hardware is guaranteed to work','The owner reported the observed problems solved in the tested candidate. That does not establish universal hardware support. Test your own display, networking, sound, input, storage and power behavior in a live session.'),*qa('Where do I find help','Open User Manual, FAQ and Installation Guide in the live welcome or Aarambh. The project website is jatayuos.in. No support response-time guarantee is implied.')])
faq.append(page('Installation and first login',*qa('Does installation erase my files','Erase disk deletes the selected disk’s contents. Manual installation can also destroy data if the wrong partition is formatted. Back up first and review the final partition summary.'),*qa('Can I keep Windows','The installer supports layout-dependent alongside and manual workflows. For Windows UEFI manual dual boot, create Linux root in prepared free space and reuse the EFI partition at /boot/efi without formatting. Preserve Windows and recovery partitions and save the BitLocker recovery key.'),*qa('Why is the installer absent after installation','Install JatayuOS is a live-media function. To reinstall, boot the ISO or USB again. An installed desktop does not need the live installer shortcuts.'),*qa('Why does the guide show different boot screens','The supplied capture is a BIOS-style VM menu. UEFI boot menus and detected disks can differ. Match your installation’s firmware mode, especially when keeping Windows.'),*qa('Will Secure Boot encryption and Android work everywhere','These are separate compatibility scenarios. Do not infer support from a successful normal VM boot or a package being included.'),*qa('How do I stop Aarambh opening at login','In the installed Aarambh view, uncheck Show Aarambh when I sign in. Aarambh remains available from the menu.'),*qa('How do I check a downloaded ISO','Run sha256sum -c SHA256SUMS in the directory containing the ISO and checksum file. Confirm the ISO reports OK and that you obtained both from a trusted source.')))
faq.append(page('Updates files and desktop behavior',*qa('Why are no updates showing after a day','That can be normal. Run sudo apt update successfully, then apt list --upgradable. An error-free refresh and an empty upgrade list mean no APT upgrade is pending from configured sources.'),*qa('What is the difference between update and upgrade','apt update refreshes package metadata. apt upgrade installs available package upgrades after you review and accept the proposal. Discover provides a graphical review and installation workflow.'),*qa('Why do GitHub fixes not appear in Discover','Debian repositories deliver Debian packages. This version has no separate signed JatayuOS package repository configured, so project-specific GitHub commits are not automatically delivered through APT.'),*qa('What does not valid yet mean in APT','A system clock behind repository timestamps can cause this error. Check timedatectl status, network connectivity and time synchronization. Do not bypass repository signature checks.'),*qa('Why are previews missing in Dolphin','Check its preview control, file format, size limits and settings. Some formats require an appropriate backend. Places shortcuts and file previews are separate features.'),*qa('Why does tapping work but the physical button does not','Those are different input paths. Compare an external mouse, tap-to-click and the physical button; inspect touchpad settings. Record the exact device and behavior before attributing it to the application launcher.'),*qa('Can I use two package managers at once','Avoid simultaneous APT and Discover package changes. Let the active transaction finish; do not delete package lock files to force another operation.')))
faq.append(page('Jatayu Tools and Android',*qa('Are Creative Studio files uploaded','Its interface and intended workflow process files locally. This does not mean external websites or every application on the OS operate offline.'),*qa('Does compression always reduce file size','No. Results depend on the original format and existing compression. Lossy settings can reduce quality. Inspect the output and keep originals.'),*qa('Why is a PDF or image conversion rejected','The file may be protected, malformed, unsupported or incompatible with the selected operation. Review the job message and test a small input first.'),*qa('Does Kavach prove that my PC is secure','No. It provides guidance and shortcuts. Check the real firewall and update settings; labels in its dashboard are not a complete live security audit.'),*qa('Are Sarkar Setu links guaranteed current','No. Service URLs and policies can change. Verify the destination in Firefox before entering credentials or submitting personal details.'),*qa('Are Utsav dates universally authoritative','No. Confirm the selected region and system date, and verify important observances against a trusted local calendar.'),*qa('Is Android ready immediately','The Waydroid package is included, but initialization and Android images are separate. Wayland, binder and graphics compatibility are required. Google apps and ARM translation are not bundled.'),*qa('Where do I find Android setup steps','Use the official instructions at docs.waydro.id/usage/install-on-desktops. This image already includes Waydroid from Debian backports; avoid adding a duplicate repository just to install the same package.')))
faq.append(page('Backups credits and support',*qa('Is Jatayu Sanjeevani a full recovery system','No. It backs up personal folders and restores into a new folder. It is not an encrypted full-system image or bootable recovery tool.'),*qa('Can I change the wallpaper offline','Yes. Open Jatayu Wallpaper Changer, choose a bundled image, set display and layout, then Apply Wallpaper. The current KDE Activity and target display matter.'),*qa('Where are software credits and licenses','Read About JatayuOS and the installed /usr/share/doc package notices. The image also contains /usr/share/jatayu/notices and a package/source-version manifest. Upstream projects retain their own authorship and licenses.'),*qa('What should a problem report include','Include build/checksum, live or installed session, hardware or VM settings, reproduction steps, expected behavior, actual result and relevant errors. Review logs and screenshots for private data before sharing.'),*qa('Is this documentation a declaration of public release','No. The guide describes JatayuOS 1.0. Consult the release page for publication status, downloads and the exact validated build.'),h('Sources'),p('Project configuration and policies: github.com/jatayuos4u/jatayuos, including apps/app.py, apps/webapp.py and docs/UPDATES.md. The screenshots and acceptance statement were supplied by the owner.'),p('Package management: <link href="https://www.debian.org/doc/manuals/debian-reference/ch02.en.html" color="#172A3D">Debian Reference Chapter 2</link>.<br/>Android setup: <link href="https://docs.waydro.id/usage/install-on-desktops" color="#172A3D">Waydroid official documentation</link>.<br/>Project website: <link href="https://jatayuos.in" color="#172A3D">jatayuos.in</link>.'),p('Screenshot dates and interface status labels belong to the captured VM session. They do not represent current information for every user.')))
save('FAQ.pdf','FAQ',faq)

